type Store struct {
	mu    sync.Mutex
	todos []Todo
}

func (s *Store) Page(limit int) []Todo {
	s.mu.Lock()
	defer s.mu.Unlock()
	if limit > len(s.todos) {
		limit = len(s.todos)
	}
	return s.todos[:limit]
}
